//! The occupancy CNN, running on the device.
//!
//! The network is C generated by ST Edge AI Core (`vendor/ai_model/`) over
//! ST's prebuilt Cortex-M33 runtime; this is the safe Rust face of it, the
//! same pattern as the VL53L5CX ULD. All the `unsafe` lives here: two buffers
//! the C code works in, and five calls into it.
//!
//! Memory, all static: the network context (~100 bytes) and 5,888 bytes of
//! activations — the scratch the layers write into, which also hold the input
//! and output tensors. The 44 KiB of weights stay in flash, `const` in the C.

pub mod bindings;

use bindings::*;

/// Class order, as trained (`tools/encode.py`: `CLASSES`).
pub const CLASSES: [&str; 3] = ["empty", "seated", "present"];
pub const MACC: u32 = STAI_OCCUPANCY_MACC_NUM;

#[derive(Clone, Copy, Debug, defmt::Format)]
pub enum Error {
    /// A `stai_*` call returned this code (see `stai.h`, `stai_return_code`).
    Stai(u32),
}

#[repr(C, align(8))]
struct Context(core::mem::MaybeUninit<_stai_occupancy_context>);

#[repr(C, align(8))]
struct Activations([u8; STAI_OCCUPANCY_ACTIVATIONS_SIZE_BYTES as usize]);

/// One classification: raw scores and the winning class.
#[derive(Clone, Copy, Debug, defmt::Format)]
pub struct Prediction {
    pub logits: [f32; 3],
    pub class: usize,
}

impl Prediction {
    /// Softmax of the logits: a confidence per class that sums to 1.
    pub fn probabilities(&self) -> [f32; 3] {
        let m = self.logits[0].max(self.logits[1]).max(self.logits[2]);
        let e = self.logits.map(|l| libm::expf(l - m));
        let s = e[0] + e[1] + e[2];
        e.map(|x| x / s)
    }
}

pub struct Model {
    net: *mut stai_network,
    input: *mut f32,
    output: *const f32,
}

fn check(rc: stai_return_code) -> Result<(), Error> {
    if rc == stai_return_code_STAI_SUCCESS {
        Ok(())
    } else {
        Err(Error::Stai(rc as u32))
    }
}

impl Model {
    /// Bring the network up. Call once; a second call returns `None` from the
    /// buffer singletons and panics, which is the point — there is one model.
    pub fn new() -> Result<Self, Error> {
        // ST's runtime checks it is on an ST part through the CRC unit, as
        // X-CUBE-AI always has; give it a clock before anything else.
        embassy_stm32::pac::RCC.ahb1enr().modify(|w| w.set_crcen(true));

        let ctx: &'static mut Context =
            cortex_m::singleton!(: Context = Context(core::mem::MaybeUninit::uninit())).unwrap();
        let act: &'static mut Activations = cortex_m::singleton!(
            : Activations = Activations([0; STAI_OCCUPANCY_ACTIVATIONS_SIZE_BYTES as usize])
        )
        .unwrap();
        let net = ctx.0.as_mut_ptr() as *mut stai_network;

        unsafe {
            check(stai_runtime_init())?;
            check(stai_occupancy_init(net))?;
            let mut act_ptr: stai_ptr = act.0.as_mut_ptr();
            check(stai_occupancy_set_activations(net, &mut act_ptr, 1))?;

            // Inputs and outputs are pre-allocated inside the activations;
            // ask where.
            let mut in_ptr: stai_ptr = core::ptr::null_mut();
            let mut n: stai_size = 0;
            check(stai_occupancy_get_inputs(net, &mut in_ptr, &mut n))?;
            let mut out_ptr: stai_ptr = core::ptr::null_mut();
            check(stai_occupancy_get_outputs(net, &mut out_ptr, &mut n))?;

            Ok(Self { net, input: in_ptr as *mut f32, output: out_ptr as *const f32 })
        }
    }

    /// Classify one encoded frame (`crate::encode::encode`).
    pub fn run(&mut self, x: &[f32; crate::encode::INPUTS]) -> Result<Prediction, Error> {
        unsafe {
            core::ptr::copy_nonoverlapping(x.as_ptr(), self.input, x.len());
            check(stai_occupancy_run(self.net, stai_run_mode::STAI_MODE_SYNC))?;
            let mut logits = [0f32; 3];
            core::ptr::copy_nonoverlapping(self.output, logits.as_mut_ptr(), 3);
            let mut class = 0;
            for i in 1..3 {
                if logits[i] > logits[class] {
                    class = i;
                }
            }
            Ok(Prediction { logits, class })
        }
    }
}
